// node composition.cjs <chunk.js>  — attribute generated bytes to source groups via its .map
const fs = require('fs');
const { SourceMapConsumer } = require(process.env.SMJS || require.resolve('source-map-js', { paths: [require('./lib.cjs').REPO_ROOT] }));
const file = process.argv[2];
const code = fs.readFileSync(file, 'utf8');
const map = JSON.parse(fs.readFileSync(file + '.map', 'utf8'));
const smc = new SourceMapConsumer(map);
const lines = code.split('\n');
const lineStart = []; let acc = 0; for (const l of lines) { lineStart.push(acc); acc += l.length + 1; }
const bySrc = {};
let prev = null;
smc.eachMapping((m) => {
  const off = lineStart[m.generatedLine - 1] + m.generatedColumn;
  if (prev) bySrc[prev.src] = (bySrc[prev.src] || 0) + (off - prev.off);
  prev = { off, src: m.source || '(none)' };
});
if (prev) bySrc[prev.src] = (bySrc[prev.src] || 0) + (code.length - prev.off);
function group(s) {
  s = s.replace(/\\/g, '/');
  let m = s.match(/node_modules\/((@[^/]+\/)?[^/]+)/); if (m) return 'npm:' + m[1];
  m = s.match(/realvirtual-WebViewer-Private~\/src\/(.*)/); if (m) { const p = m[1].split('/'); return 'private:' + p.slice(0, Math.min(p.length - 1, 2)).join('/'); }
  m = s.match(/realvirtual-WebViewer~\/src\/(.*)/); if (m) { const p = m[1].split('/'); return 'src:' + p.slice(0, Math.min(p.length - 1, 2)).join('/'); }
  return 'other:' + s.slice(-60);
}
const g = {}; for (const [s, b] of Object.entries(bySrc)) { const k = group(s); g[k] = (g[k] || 0) + b; }
const total = code.length;
console.log('total', (total / 1e6).toFixed(2), 'MB raw');
for (const [k, b] of Object.entries(g).sort((a, b) => b[1] - a[1]).slice(0, Number(process.argv[3] || 45)))
  console.log(String((b / 1024).toFixed(0)).padStart(6), 'KB', ((100 * b) / total).toFixed(1).padStart(5) + '%', k);
if (process.argv[4]) {
  console.log('\n--- top single files ---');
  for (const [s, b] of Object.entries(bySrc).sort((a, b) => b[1] - a[1]).slice(0, 40)) console.log(String((b / 1024).toFixed(0)).padStart(6), 'KB', s.replace(/^.*?(node_modules|src)\//, '$1/'));
}
